  for (const eligibleRowCount of [2999, 3000, 7000, 7001]) {
    const densityTable = createColumnarPanelResult(
      ['x', 'y', 'open', 'high', 'low', 'close'],
      eligibleRowCount,
      (rowIndex, columnIndex) => {
        if (columnIndex === 0) {
          return rowIndex;
        }
        if (columnIndex === 1 || columnIndex === 2) {
          return rowIndex + 10;
        }
        if (columnIndex === 3) {
          return rowIndex + 12;
        }
        if (columnIndex === 4) {
          return rowIndex + 8;
        }
        return rowIndex + 11;
      },
      ['int', 'int', 'int', 'int', 'int', 'int']
    );
    for (const chartType of ['line', 'scatter', 'step', 'bar', 'box', 'candlestick']) {
      const ranged = buildChartData(densityTable, {
        chartType,
        xColumn: 'x',
        yColumns: chartType === 'candlestick' ? [] : ['y'],
        openColumn: 'open',
        highColumn: 'high',
        lowColumn: 'low',
        closeColumn: 'close',
        xMin: 0,
        xMax: eligibleRowCount - 1,
        width: 1,
        maxSampledPoints: 9000,
        maxSourceRows: 8000,
        version: 1,
        requestId: eligibleRowCount,
      });
      const expectedPointCount = chartType === 'bar'
        ? Math.min(eligibleRowCount, 200)
        : chartType === 'box'
          ? Math.min(eligibleRowCount, 25)
          : chartType === 'candlestick'
            ? 1
            : Math.min(eligibleRowCount, 7000);
      assert.strictEqual(
        ranged.eligibleRowCount,
        eligibleRowCount,
        `${chartType} must count every source row eligible for the ranged request at ${eligibleRowCount}`
      );
      assert.strictEqual(
        ranged.sampledPointCount,
        expectedPointCount,
        `${chartType} must use its honest ranged family target at ${eligibleRowCount}`
      );
      assert.strictEqual(
        ranged.x.length,
        expectedPointCount,
        `${chartType} ranged output x count must match its reported sampled count`
      );
      assert.strictEqual(
        new Set(ranged.x).size,
        expectedPointCount,
        `${chartType} must preserve the exact unique-x count for the threshold fixture`
      );
      const expectedAlgorithm = chartType === 'bar'
        ? (eligibleRowCount <= 200
          ? `bar-cluster/${eligibleRowCount}`
          : 'bar-cluster-even/200')
        : chartType === 'box'
          ? (eligibleRowCount <= 25
            ? `box-exact/${eligibleRowCount}`
            : 'box-bucket/25')
          : chartType === 'candlestick'
            ? (eligibleRowCount === 1 ? 'ohlc-exact/1' : 'ohlc-bucket/1')
            : (eligibleRowCount <= 7000 ? 'none' : 'minmax-bucket/7000');
      assert.strictEqual(
        ranged.algorithm,
        expectedAlgorithm,
        `${chartType} must report the exact ranged threshold algorithm at ${eligibleRowCount}`
      );
      if (chartType === 'candlestick') {
        assert.strictEqual(ranged.candlesticks.length, expectedPointCount);
      }
      if (chartType === 'box') {
        assert.strictEqual(ranged.boxSeries[0].stats.length, expectedPointCount);
      }
      if (chartType !== 'box' && chartType !== 'candlestick') {
        assert.strictEqual(
          ranged.series[0].values.length,
          expectedPointCount,
          `${chartType} ranged series values must retain the asserted threshold density`
        );
      }
      const fullView = buildChartData(densityTable, {
        chartType,
        xColumn: 'x',
        yColumns: chartType === 'candlestick' ? [] : ['y'],
        openColumn: 'open',
        highColumn: 'high',
        lowColumn: 'low',
        closeColumn: 'close',
        width: 1,
        maxSampledPoints: 9000,
        maxSourceRows: 8000,
        version: 1,
        requestId: eligibleRowCount + 1,
      });
      assert.strictEqual(fullView.eligibleRowCount, eligibleRowCount);
      assert.strictEqual(
        fullView.sampledPointCount,
        expectedPointCount,
        `${chartType} full and ranged paths must share the same family target`
      );
      assert.strictEqual(fullView.x.length, expectedPointCount);
      assert.strictEqual(new Set(fullView.x).size, expectedPointCount);
      assert.strictEqual(fullView.algorithm, expectedAlgorithm);
    }
  }
