function requireOut(moduleName) {
  const candidates = [
    path.join(TEST_OUT_ROOT, moduleName),
    path.join(TEST_OUT_ROOT, 'src', moduleName),
  ];
  for (const candidate of candidates) {
    try {
      return require(candidate);
    } catch (error) {
      if (error && error.code !== 'MODULE_NOT_FOUND') {
        throw error;
      }
    }
  }
  throw new Error(`Compiled module out/${moduleName}.js is missing. Run npm run compile first.`);
}

function requireOutWithVscode(moduleName, vscode) {
  return requireOutWithMocks(moduleName, { vscode });
}

function requireOutWithMocks(moduleName, mocks) {
  const candidates = [
    path.join(TEST_OUT_ROOT, moduleName),
    path.join(TEST_OUT_ROOT, 'src', moduleName),
  ];
  for (const candidate of candidates) {
    let resolved;
    try {
      resolved = require.resolve(candidate);
    } catch (error) {
      if (error && error.code === 'MODULE_NOT_FOUND') {
        continue;
      }
      throw error;
    }
    for (const cached of Object.keys(require.cache)) {
      const relative = path.relative(TEST_OUT_ROOT, cached);
      if (relative && !relative.startsWith(`..${path.sep}`) && relative !== '..' &&
        !path.isAbsolute(relative)) {
        delete require.cache[cached];
      }
    }
    const originalLoad = Module._load;
    Module._load = function loadWithMocks(request, parent, isMain) {
      return Object.prototype.hasOwnProperty.call(mocks, request)
        ? mocks[request]
        : originalLoad.call(this, request, parent, isMain);
    };
    try {
      return require(resolved);
    } finally {
      Module._load = originalLoad;
    }
  }
  throw new Error(`Compiled module out/${moduleName}.js is missing. Run npm run compile first.`);
}

function modelQTable(columns, rows) {
  return {
    qtype: 'table',
    columns: columns.slice(),
    rows: rows.map(row => ({ ...row })),
    columnData: [],
    rowCount: rows.length,
  };
}

function historyEntry(overrides = {}) {
  return {
    id: 'entry-default',
    connectionId: 'kx-history',
    connectionName: 'History q',
    timestamp: 100,
    kind: 'line',
    status: 'succeeded',
    durationMs: 5,
    queryText: '1+1',
    ...overrides,
  };
}

function cloneMaybe(value) {
  return value === undefined ? undefined : cloneJson(value);
}

function createHistoryMemento(initialValue) {
  let stored = cloneMaybe(initialValue);
  const updates = [];
  return {
    get(key) {
      assert.strictEqual(key, QUERY_HISTORY_STORAGE_KEY);
      return cloneMaybe(stored);
    },
    async update(key, value) {
      assert.strictEqual(key, QUERY_HISTORY_STORAGE_KEY);
      await Promise.resolve();
      stored = cloneMaybe(value);
      updates.push(cloneMaybe(value));
    },
    get value() {
      return cloneMaybe(stored);
    },
    updates,
  };
}

function createBlockingHistoryMemento(initialValue) {
  let stored = cloneMaybe(initialValue);
  let firstUpdate = true;
  let markUpdateStarted;
  let releaseUpdate;
  const updateStarted = new Promise(resolve => {
    markUpdateStarted = resolve;
  });
  const gate = new Promise(resolve => {
    releaseUpdate = resolve;
  });
  const updates = [];
  return {
    get(key) {
      assert.strictEqual(key, QUERY_HISTORY_STORAGE_KEY);
      return cloneMaybe(stored);
    },
    async update(key, value) {
      assert.strictEqual(key, QUERY_HISTORY_STORAGE_KEY);
      if (firstUpdate) {
        firstUpdate = false;
        markUpdateStarted();
        await gate;
      }
      stored = cloneMaybe(value);
      updates.push(cloneMaybe(value));
    },
    get value() {
      return cloneMaybe(stored);
    },
    updateStarted,
    releaseUpdate,
    updates,
  };
}

function assertHistoryStorageShape(value) {
  assert.ok(Array.isArray(value));
  const allowed = ['connectionId', 'connectionName', 'durationMs', 'id', 'kind', 'queryText', 'status', 'timestamp'];
  value.forEach(entry => {
    assert.deepStrictEqual(Object.keys(entry).sort(), allowed);
    for (const forbidden of ['result', 'results', 'password', 'username', 'host', 'error', 'messages']) {
      assert.strictEqual(Object.prototype.hasOwnProperty.call(entry, forbidden), false);
    }
  });
}

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function eventLoopTurn() {
  return new Promise(resolve => setImmediate(resolve));
}

function createNotebookIntegrationRuntime() {
  const commands = new Map();
  const contexts = [];
  const warnings = [];
  const information = [];
  const errors = [];
  const statusProviders = [];
  const workspaceEdits = [];
  const quickPickCalls = [];
  const warningCalls = [];
  const postedMessages = [];
  const clipboardWrites = [];
  const executedCommands = [];
  const savedFiles = [];
  const configuration = new Map([
    ['vscode-kdb.notebook.maxOutputRows', 2],
    ['vscode-kdb.notebook.maxOutputBytes', MAX_NOTEBOOK_BYTE_LIMIT],
  ]);
  let quickPickSelectionId;
  let warningResponse;
  let saveDialogUri = testUri('file:///workspace/kx-results.csv');
  let applyEditResult = true;
  let replacementCellId = 0;
  let notebookEditMode = 'new-uri';
  let deferNotebookReconciliation = false;
  let beforeNotebookEditCommit;

  class EventEmitter {
    constructor() {
      this.listeners = new Set();
      this.disposed = false;
      this.event = listener => {
        if (this.disposed) {
          return { dispose() {} };
        }
        this.listeners.add(listener);
        let active = true;
        return {
          dispose: () => {
            if (!active) {
              return;
            }
            active = false;
            this.listeners.delete(listener);
          },
        };
      };
    }

    fire(value) {
      for (const listener of [...this.listeners]) {
        listener(value);
      }
    }

    dispose() {
      this.disposed = true;
      this.listeners.clear();
    }
  }

  class NotebookCellStatusBarItem {
    constructor(text, alignment) {
      this.text = text;
      this.alignment = alignment;
    }
  }

  class NotebookCellOutput {
    constructor(items, metadata = {}) {
      this.items = items;
      this.metadata = metadata;
    }
  }

  class NotebookCellData {
    constructor(kind, value, languageId) {
      this.kind = kind;
      this.value = value;
      this.languageId = languageId;
      this.outputs = undefined;
      this.metadata = undefined;
      this.executionSummary = undefined;
    }
  }

  class NotebookRange {
    constructor(start, end) {
      this.start = Math.min(start, end);
      this.end = Math.max(start, end);
      this.isEmpty = this.start === this.end;
    }
  }

  class WorkspaceEdit {
    constructor() {
      this.entries = [];
    }

    set(uri, edits) {
      this.entries.push({ uri, edits });
    }
  }

  const activeNotebookChanged = new EventEmitter();
  const notebookSelectionChanged = new EventEmitter();
  const notebookDocumentChanged = new EventEmitter();
  const configurationChanged = new EventEmitter();
  const rendererMessages = new EventEmitter();
  const disposable = dispose => ({ dispose: dispose || (() => undefined) });
  const vscode = {
    EventEmitter,
    NotebookCellKind: {
      Markup: 1,
      Code: 2,
    },
    NotebookCellStatusBarAlignment: {
      Left: 1,
      Right: 2,
    },
    ProgressLocation: {
      Notification: 15,
    },
    NotebookCellStatusBarItem,
    NotebookCellOutput,
    NotebookCellData,
    NotebookRange,
    NotebookEdit: {
      updateNotebookMetadata(metadata) {
        return { kind: 'updateNotebookMetadata', metadata };
      },
      replaceCells(range, newCells) {
        return { kind: 'replaceCells', range, newCells };
      },
    },
    NotebookCellOutputItem: {
      json(value, mime) {
        return {
          kind: 'json',
          mime,
          data: new TextEncoder().encode(JSON.stringify(value)),
        };
      },
      text(value, mime = 'text/plain') {
        return {
          kind: 'text',
          mime,
          data: new TextEncoder().encode(value),
        };
      },
      error(error) {
        return {
          kind: 'error',
          mime: 'application/vnd.code.notebook.error',
          data: new TextEncoder().encode(JSON.stringify({
            name: error.name,
            message: error.message,
            stack: error.stack,
          })),
        };
      },
    },
    WorkspaceEdit,
    window: {
      activeNotebookEditor: undefined,
      activeTextEditor: undefined,
      onDidChangeActiveNotebookEditor: activeNotebookChanged.event,
      onDidChangeNotebookEditorSelection: notebookSelectionChanged.event,
      showWarningMessage(message, ...items) {
        warnings.push(message);
        warningCalls.push({ message, items });
        return Promise.resolve(warningResponse);
      },
      showInformationMessage(message) {
        information.push(message);
        return Promise.resolve(undefined);
      },
      showErrorMessage(message) {
        errors.push(message);
        return Promise.resolve(undefined);
      },
      showQuickPick(items, options) {
        quickPickCalls.push({ items, options });
        const picked = quickPickSelectionId === null
          ? undefined
          : quickPickSelectionId
          ? items.find(item => item.profile?.id === quickPickSelectionId)
          : items[0];
        return Promise.resolve(picked);
      },
      showSaveDialog() {
        return Promise.resolve(saveDialogUri);
      },
      withProgress(_options, task) {
        const token = {
          isCancellationRequested: false,
          onCancellationRequested() {
            return disposable();
          },
        };
        return task({ report() {} }, token);
      },
    },
    workspace: {
      workspaceFolders: [],
      fs: {
        async writeFile(uri, content) {
          savedFiles.push({ uri, content: Uint8Array.from(content) });
        },
      },
      onDidChangeNotebookDocument: notebookDocumentChanged.event,
      onDidChangeConfiguration: configurationChanged.event,
      async applyEdit(edit) {
        workspaceEdits.push(edit);
        if (!applyEditResult) {
          return false;
        }
        const notebook = vscode.window.activeNotebookEditor?.notebook;
        if (!notebook || edit.entries.some(entry =>
          entry.uri.toString() !== notebook.uri.toString())) {
          return false;
        }
        const commit = () => {
          const contentChanges = [];
          const cellChanges = [];
          for (const entry of edit.entries) {
            for (const notebookEdit of entry.edits) {
              if (notebookEdit.kind === 'updateNotebookMetadata') {
                notebook.metadata = notebookEdit.metadata;
                continue;
              }
              if (notebookEdit.kind !== 'replaceCells') {
                throw new Error(`unsupported notebook edit ${notebookEdit.kind}`);
              }
              const removed = notebook.cells.slice(
                notebookEdit.range.start,
                notebookEdit.range.end
              );
              let replacements;
              if (notebookEditMode === 'same-uri') {
                replacements = notebookEdit.newCells.map((data, offset) => {
                  const existing = removed[offset];
                  if (!existing) {
                    throw new Error('same-URI notebook replacement requires an existing cell');
                  }
                  const source = data.value;
                  existing.index = notebookEdit.range.start + offset;
                  existing.kind = data.kind;
                  existing.document = {
                    languageId: data.languageId,
                    uri: existing.document.uri,
                    version: (existing.document.version || 0) + 1,
                    getText: () => source,
                  };
                  existing.metadata = cloneNotebookHostValue(data.metadata || {});
                  existing.outputs = (data.outputs || []).map(output =>
                    new NotebookCellOutput(
                      output.items.map(item => cloneNotebookHostValue(item)),
                      cloneNotebookHostValue(output.metadata)
                    )
                  );
                  existing.executionSummary = data.executionSummary;
                  return existing;
                });
                notebook.cells.splice(
                  notebookEdit.range.start,
                  notebookEdit.range.end - notebookEdit.range.start,
                  ...replacements
                );
                cellChanges.push(...replacements.map(cell => ({
                  cell,
                  outputs: cell.outputs,
                })));
              } else {
                replacements = notebookEdit.newCells.map((data, offset) => {
                  const source = data.value;
                  return {
                    notebook,
                    index: notebookEdit.range.start + offset,
                    kind: data.kind,
                    document: {
                      languageId: data.languageId,
                      uri: testUri(
                        `${removed[offset]?.document.uri.toString() || 'vscode-notebook-cell:///mixed'}` +
                        `?replacement=${++replacementCellId}`
                      ),
                      version: (removed[offset]?.document.version || 0) + 1,
                      getText: () => source,
                    },
                    metadata: cloneNotebookHostValue(data.metadata || {}),
                    outputs: (data.outputs || []).map(output =>
                      new NotebookCellOutput(
                        output.items.map(item => cloneNotebookHostValue(item)),
                        cloneNotebookHostValue(output.metadata)
                      )
                    ),
                    executionSummary: data.executionSummary,
                  };
                });
                notebook.cells.splice(
                  notebookEdit.range.start,
                  notebookEdit.range.end - notebookEdit.range.start,
                  ...replacements
                );
                contentChanges.push({
                  range: notebookEdit.range,
                  removedCells: removed,
                  addedCells: replacements,
                });
              }
              notebook.version += 1;
            }
          }
          notebook.cellCount = notebook.cells.length;
          notebookDocumentChanged.fire({
            notebook,
            metadata: notebook.metadata,
            contentChanges,
            cellChanges,
          });
        };
        if (beforeNotebookEditCommit) {
          const hook = beforeNotebookEditCommit;
          beforeNotebookEditCommit = undefined;
          const handled = await hook(notebook, edit, commit);
          if (handled === true) {
            return true;
          }
        }
        if (deferNotebookReconciliation) {
          setImmediate(commit);
        } else {
          commit();
        }
        return true;
      },
      getConfiguration(section) {
        return {
          get(key, fallback) {
            const fullKey = `${section}.${key}`;
            return configuration.has(fullKey) ? configuration.get(fullKey) : fallback;
          },
        };
      },
    },
    Uri: {
      file(filePath) {
        return {
          fsPath: filePath,
          toString() {
            return `file://${filePath}`;
          },
        };
      },
    },
    env: {
      clipboard: {
        async writeText(text) {
          clipboardWrites.push(text);
        },
      },
    },
    languages: {
      async setTextDocumentLanguage(document, languageId) {
        document.languageId = languageId;
        return document;
      },
      async getLanguages() {
        return ['python', 'q', 'markdown'];
      },
    },
    commands: {
      registerCommand(id, handler) {
        commands.set(id, handler);
        return disposable(() => commands.delete(id));
      },
      executeCommand(id, ...args) {
        if (id === 'setContext') {
          contexts.push({ key: args[0], value: args[1] });
          return Promise.resolve(undefined);
        }
        executedCommands.push({ id, args });
        const handler = commands.get(id);
        return handler ? Promise.resolve(handler(...args)) : Promise.resolve(undefined);
      },
    },
    notebooks: {
      createRendererMessaging() {
        return {
          onDidReceiveMessage: rendererMessages.event,
          async postMessage(message, editor) {
            postedMessages.push({ message, editor });
            return true;
          },
        };
      },
      registerNotebookCellStatusBarItemProvider(notebookType, provider) {
        const registration = { notebookType, provider };
        statusProviders.push(registration);
        return disposable(() => {
          const index = statusProviders.indexOf(registration);
          if (index >= 0) {
            statusProviders.splice(index, 1);
          }
        });
      },
    },
  };

  return {
    vscode,
    commands,
    contexts,
    warnings,
    information,
    errors,
    statusProviders,
    workspaceEdits,
    quickPickCalls,
    warningCalls,
    postedMessages,
    clipboardWrites,
    executedCommands,
    savedFiles,
    async emitRendererMessage(editor, message) {
      rendererMessages.fire({ editor, message });
      await eventLoopTurn();
      await eventLoopTurn();
    },
    setQuickPickSelectionId(value) {
      quickPickSelectionId = value;
    },
    setWarningResponse(value) {
      warningResponse = value;
    },
    setSaveDialogUri(value) {
      saveDialogUri = value;
    },
    setApplyEditResult(value) {
      applyEditResult = value;
    },
    setNotebookEditMode(mode, deferReconciliation = false) {
      assert.ok(mode === 'new-uri' || mode === 'same-uri');
      notebookEditMode = mode;
      deferNotebookReconciliation = deferReconciliation;
    },
    setBeforeNotebookEditCommit(value) {
      beforeNotebookEditCommit = value;
    },
    setConfiguration(key, value) {
      configuration.set(key, value);
    },
    cell(notebook, index, languageId, source) {
      const document = {
        languageId,
        uri: testUri(`vscode-notebook-cell:///mixed/${index}`),
        version: 1,
        getText: () => source,
      };
      return {
        notebook,
        index,
        kind: vscode.NotebookCellKind.Code,
        document,
        metadata: {},
        outputs: languageId === 'python' ? [{ owner: 'python-controller' }] : [],
      };
    },
  };
}

function createNotebookControllerRuntime() {
  const controllers = [];
  const executions = [];
  const createExecutionCalls = [];
  const workspaceEdits = [];
  const progressRuns = [];
  const replacements = new Map();
  const notebooksByUri = new Map();
  let replacementId = 0;
  const controls = {
    applyEditResult: true,
    applyEditThrows: false,
    beforeApplyEdit: undefined,
    deferNotebookCommit: false,
    deferNotebookEvent: false,
    normalizeNotebookOutput: undefined,
    onWorkspaceEditConstruct: undefined,
    preCancelProgress: false,
    skipDeferredNotebookCommit: false,
  };
  const configuration = new Map([
    ['vscode-kdb.notebook.enableDirectController', false],
    ['vscode-kdb.notebook.maxOutputRows', 2],
    ['vscode-kdb.notebook.maxOutputBytes', 4096],
    ['vscode-kdb.results.viewer.dictionaryDisplayStrategy', 'grid'],
    ['vscode-kdb.results.viewer.listDisplayStrategy', 'grid'],
  ]);

  class EventEmitter {
    constructor() {
      this.listeners = new Set();
      this.disposed = false;
      this.event = listener => {
        if (this.disposed) {
          return { dispose() {} };
        }
        this.listeners.add(listener);
        let active = true;
        return {
          dispose: () => {
            if (!active) {
              return;
            }
            active = false;
            this.listeners.delete(listener);
          },
        };
      };
    }

    get listenerCount() {
      return this.listeners.size;
    }

    fire(value) {
      for (const listener of [...this.listeners]) {
        listener(value);
      }
    }

    dispose() {
      this.disposed = true;
      this.listeners.clear();
    }
  }

  const notebookChanges = new EventEmitter();
  const configurationChanges = new EventEmitter();

  class NotebookCellOutput {
    constructor(items, metadata = {}) {
      this.items = items;
      this.metadata = metadata;
    }
  }

  class NotebookCellData {
    constructor(kind, value, languageId) {
      this.kind = kind;
      this.value = value;
      this.languageId = languageId;
      this.outputs = undefined;
      this.metadata = undefined;
      this.executionSummary = undefined;
    }
  }

  class NotebookRange {
    constructor(start, end) {
      this.start = Math.min(start, end);
      this.end = Math.max(start, end);
      this.isEmpty = this.start === this.end;
    }
  }

  class NotebookEdit {
    static replaceCells(range, newCells) {
      return { kind: 'replaceCells', range, newCells };
    }
  }

  class WorkspaceEdit {
    constructor() {
      this.entries = [];
      controls.onWorkspaceEditConstruct?.();
    }

    set(uri, edits) {
      const notebook = notebooksByUri.get(uri.toString());
      this.entries.push({
        uri,
        edits,
        version: notebook?.version,
      });
    }
  }

  class CancellationToken {
    constructor(preCanceled) {
      this.canceled = !!preCanceled;
      this.listeners = new Set();
    }

    get isCancellationRequested() {
      return this.canceled;
    }

    onCancellationRequested(listener) {
      this.listeners.add(listener);
      return { dispose: () => this.listeners.delete(listener) };
    }

    cancel() {
      if (this.canceled) {
        return;
      }
      this.canceled = true;
      for (const listener of [...this.listeners]) {
        listener();
      }
    }
  }

  function makeCell({
    kind = 2,
    languageId = 'q',
    source = '',
    uri = `vscode-notebook-cell:///cell/${replacementId + 1}`,
    metadata = {},
    outputs = [],
    executionSummary,
    preCanceled = false,
    startThrows = false,
    endThrows = false,
    createExecutionThrows = false,
  } = {}) {
    const cell = {
      kind,
      preCanceled,
      startThrows,
      endThrows,
      createExecutionThrows,
      metadata,
      outputs,
      executionSummary,
      _notebook: undefined,
      _source: source,
      document: {
        languageId,
        uri: testUri(uri),
        getText: () => cell._source,
      },
    };
    Object.defineProperties(cell, {
      notebook: {
        enumerable: true,
        get() {
          return this._notebook;
        },
        set(value) {
          if (this._notebook === value) {
            return;
          }
          if (this._notebook) {
            const previousIndex = this._notebook.cells.indexOf(this);
            if (previousIndex >= 0) {
              this._notebook.cells.splice(previousIndex, 1);
            }
          }
          this._notebook = value;
          if (value && !value.cells.includes(this)) {
            value.cells.push(this);
          }
        },
      },
      index: {
        enumerable: true,
        get() {
          return this._notebook ? this._notebook.cells.indexOf(this) : -1;
        },
      },
    });
    return cell;
  }

  function createExecution(cell) {
    const token = new CancellationToken(cell.preCanceled);
    const execution = {
      cell,
      token,
      executionOrder: undefined,
      startCalls: [],
      endCalls: [],
      clearOutputCalls: 0,
      replaceOutputCalls: [],
      output: undefined,
      start(time) {
        this.startCalls.push(time);
        if (cell.startThrows) {
          throw new Error('injected notebook execution start failure');
        }
      },
      end(success, time) {
        this.endCalls.push({ success, time });
        if (cell.endThrows) {
          throw new Error('injected notebook execution end failure');
        }
      },
      async clearOutput() {
        this.clearOutputCalls += 1;
        this.output = undefined;
        cell.outputs = [];
      },
      async replaceOutput(output) {
        this.replaceOutputCalls.push(output);
        this.output = output;
        cell.outputs = Array.isArray(output) ? [...output] : [output];
      },
    };
    executions.push(execution);
    return execution;
  }

  function notebookCommittedOutputs(outputs) {
    return (outputs || []).map(output => {
      if (typeof controls.normalizeNotebookOutput !== 'function') {
        return output;
      }
      const normalized = controls.normalizeNotebookOutput(output);
      return new NotebookCellOutput(
        (normalized.items || []).map(item => cloneNotebookHostValue(item)),
        cloneNotebookHostValue(normalized.metadata)
      );
    });
  }

  const vscode = {
    EventEmitter,
    NotebookCellKind: {
      Markup: 1,
      Code: 2,
    },
    NotebookCellOutput,
    NotebookCellData,
    NotebookRange,
    NotebookEdit,
    WorkspaceEdit,
    ProgressLocation: {
      Notification: 15,
    },
    NotebookCellOutputItem: {
      json(value, mime) {
        return { kind: 'json', mime, value };
      },
      text(value, mime = 'text/plain') {
        return { kind: 'text', mime, value };
      },
      error(error) {
        return {
          kind: 'error',
          mime: 'application/vnd.code.notebook.error',
          error,
        };
      },
    },
    workspace: {
      onDidChangeNotebookDocument: notebookChanges.event,
      onDidChangeConfiguration: configurationChanges.event,
      async applyEdit(edit) {
        workspaceEdits.push(edit);
        if (typeof controls.beforeApplyEdit === 'function') {
          await controls.beforeApplyEdit(edit);
        }
        if (controls.applyEditThrows) {
          throw new Error('injected workspace edit failure');
        }
        if (!controls.applyEditResult) {
          return false;
        }
        const commit = () => {
          for (const entry of edit.entries) {
            const notebook = notebooksByUri.get(entry.uri.toString());
            if (!notebook || notebook.isClosed || notebook.version !== entry.version) {
              return false;
            }
            for (const notebookEdit of entry.edits) {
              if (notebookEdit.kind !== 'replaceCells') {
                throw new Error(`unsupported notebook edit ${notebookEdit.kind}`);
              }
              const removedCells = notebook.cells.slice(
                notebookEdit.range.start,
                notebookEdit.range.end
              );
              const addedCells = notebookEdit.newCells.map(data => {
                const replacement = makeCell({
                  kind: data.kind,
                  languageId: data.languageId,
                  source: data.value,
                  uri: `${removedCells[0]?.document.uri.toString() || 'vscode-notebook-cell:///cell'}` +
                    `?replacement=${++replacementId}`,
                  metadata: data.metadata,
                  outputs: notebookCommittedOutputs(data.outputs),
                  executionSummary: data.executionSummary,
                });
                replacement._notebook = notebook;
                return replacement;
              });
              notebook.cells.splice(
                notebookEdit.range.start,
                notebookEdit.range.end - notebookEdit.range.start,
                ...addedCells
              );
              removedCells.forEach((removed, removedIndex) => {
                if (addedCells[removedIndex]) {
                  replacements.set(removed, addedCells[removedIndex]);
                }
              });
              for (const removed of removedCells) {
                removed._notebook = notebook;
              }
              notebook.version += 1;
              const event = {
                notebook,
                metadata: undefined,
                contentChanges: [{
                  range: notebookEdit.range,
                  addedCells,
                  removedCells,
                }],
                cellChanges: [],
              };
              if (controls.deferNotebookEvent) {
                setTimeout(() => notebookChanges.fire(event), 0);
              } else {
                notebookChanges.fire(event);
              }
            }
          }
          return true;
        };
        if (controls.deferNotebookCommit) {
          if (!controls.skipDeferredNotebookCommit) {
            setTimeout(commit, 0);
          }
          return true;
        }
        return commit();
      },
      getConfiguration(section) {
        return {
          get(key, fallback) {
            const setting = `${section}.${key}`;
            return configuration.has(setting) ? configuration.get(setting) : fallback;
          },
        };
      },
    },
    window: {
      withProgress(options, task) {
        const token = new CancellationToken(controls.preCancelProgress);
        const run = { options, token };
        progressRuns.push(run);
        return task({ report() {} }, token);
      },
    },
    notebooks: {
      createNotebookController(id, notebookType, label, executeHandler) {
        const selectionEmitter = new EventEmitter();
        const selectedNotebooks = new Set();
        const fireSelection = selectionEmitter.fire.bind(selectionEmitter);
        selectionEmitter.fire = event => {
          const key = event.notebook.uri.toString();
          if (event.selected) {
            selectedNotebooks.add(key);
          } else {
            selectedNotebooks.delete(key);
          }
          fireSelection(event);
        };
        const controller = {
          id,
          notebookType,
          label,
          executeHandler(cells, notebook, ...args) {
            for (const cell of cells) {
              cell.notebook = notebook;
            }
            return executeHandler(cells, notebook, ...args);
          },
          selectionEmitter,
          onDidChangeSelectedNotebooks: selectionEmitter.event,
          supportedLanguages: undefined,
          supportsExecutionOrder: false,
          description: undefined,
          detail: undefined,
          disposeCalls: 0,
          createNotebookCellExecution(cell) {
            createExecutionCalls.push(cell);
            if (!cell.notebook ||
              !selectedNotebooks.has(cell.notebook.uri.toString())) {
              throw new Error(
                'Notebook controller is not associated with the target notebook'
              );
            }
            if (cell.createExecutionThrows) {
              throw new Error('injected duplicate execution');
            }
            return createExecution(cell);
          },
          dispose() {
            this.disposeCalls += 1;
          },
        };
        controllers.push(controller);
        return controller;
      },
    },
  };

  return {
    vscode,
    controllers,
    executions,
    createExecutionCalls,
    workspaceEdits,
    progressRuns,
    controls,
    setDirectControllerEnabled(enabled) {
      configuration.set('vscode-kdb.notebook.enableDirectController', enabled);
      configurationChanges.fire({
        affectsConfiguration(key) {
          return key === 'vscode-kdb.notebook.enableDirectController';
        },
      });
    },
    setConfiguration(key, value) {
      configuration.set(key, value);
    },
    cell({
      kind = vscode.NotebookCellKind.Code,
      languageId = 'q',
      source = '',
      uri = `vscode-notebook-cell:///cell/${executions.length}`,
      preCanceled = false,
      startThrows = false,
      endThrows = false,
      createExecutionThrows = false,
    } = {}) {
      return makeCell({
        kind,
        languageId,
        source,
        uri,
        preCanceled,
        startThrows,
        endThrows,
        createExecutionThrows,
      });
    },
    notebook(uri) {
      const notebook = {
        uri: testUri(uri),
        notebookType: 'jupyter-notebook',
        version: 1,
        isClosed: false,
        cells: [],
        get cellCount() {
          return this.cells.length;
        },
        cellAt(index) {
          return this.cells[index];
        },
        getCells(range) {
          return range
            ? this.cells.slice(range.start, range.end)
            : this.cells.slice();
        },
      };
      notebooksByUri.set(notebook.uri.toString(), notebook);
      return notebook;
    },
    executionFor(cell) {
      return executions.filter(execution => execution.cell === cell).at(-1);
    },
    outputFor(cell) {
      return cell.outputs[0];
    },
    replacementFor(cell) {
      return replacements.get(cell);
    },
    emitNotebookCellOutputs(cell, outputs) {
      if (!cell?.notebook) {
        throw new Error('cannot emit notebook outputs for a detached cell');
      }
      cell.outputs = outputs;
      notebookChanges.fire({
        notebook: cell.notebook,
        metadata: undefined,
        contentChanges: [],
        cellChanges: [{ cell, outputs }],
      });
    },
    touchCell(cell, changes = {}) {
      if (Object.prototype.hasOwnProperty.call(changes, 'source')) {
        cell._source = changes.source;
      }
      if (Object.prototype.hasOwnProperty.call(changes, 'languageId')) {
        cell.document.languageId = changes.languageId;
      }
      if (Object.prototype.hasOwnProperty.call(changes, 'outputs')) {
        cell.outputs = changes.outputs;
      }
      if (Object.prototype.hasOwnProperty.call(changes, 'executionSummary')) {
        cell.executionSummary = changes.executionSummary;
      }
      if (cell.notebook) {
        cell.notebook.version += 1;
      }
    },
  };
}

function createDirectQNotebookBridgeHarness() {
  const listeners = new Set();
  return {
    connection: undefined,
    connected: false,
    calls: [],
    errorTargets: [],
    stateSubscriptionDisposals: 0,
    executeImpl: async (_connection, _source, onIssued) => {
      onIssued();
      return 1;
    },
    errorImpl: async error => error instanceof Error ? error.message : String(error),
    activeConnection() {
      return this.connection;
    },
    connections() {
      return this.connectionList || (this.connection ? [this.connection] : []);
    },
    connectionById(connectionId) {
      return this.connections().find(connection => connection.id === connectionId);
    },
    isConnected(connectionId) {
      return !!this.connection && this.connection.id === connectionId && this.connected;
    },
    async executeScript(connection, source, onIssued, signal, shouldIssue) {
      this.calls.push({ connection, source, signal, shouldIssue });
      return this.executeImpl(connection, source, onIssued, signal, shouldIssue);
    },
    async errorMessage(error, connection) {
      return this.errorImpl(error, connection);
    },
    onDidChangeState(listener) {
      listeners.add(listener);
      let active = true;
      return {
        dispose: () => {
          if (!active) {
            return;
          }
          active = false;
          listeners.delete(listener);
          this.stateSubscriptionDisposals += 1;
        },
      };
    },
    fireState() {
      for (const listener of [...listeners]) {
        listener();
      }
    },
  };
}

function testUri(value) {
  return {
    toString() {
      return value;
    },
  };
}

function notebookOutputItem(output, mime) {
  return output && Array.isArray(output.items)
    ? output.items.find(item => item.mime === mime)
    : undefined;
}

function notebookOutputItemJsonByteLength(item) {
  if (!item) {
    return 0;
  }
  if (item.data instanceof Uint8Array) {
    return item.data.byteLength;
  }
  if (Object.prototype.hasOwnProperty.call(item, 'value')) {
    return Buffer.byteLength(JSON.stringify(item.value), 'utf8');
  }
  return 0;
}

function workspaceEditKxMimeByteLength(edit) {
  let maxBytes = 0;
  for (const entry of edit.entries || []) {
    for (const notebookEdit of entry.edits || []) {
      for (const cell of notebookEdit.newCells || []) {
        for (const output of cell.outputs || []) {
          const item = notebookOutputItem(output, KX_NOTEBOOK_MIME);
          maxBytes = Math.max(maxBytes, notebookOutputItemJsonByteLength(item));
        }
      }
    }
  }
  return maxBytes;
}

function notebookErrorText(output) {
  const item = output && Array.isArray(output.items)
    ? output.items.find(candidate => candidate.kind === 'error')
    : undefined;
  return item?.error?.stack || item?.error?.message || '';
}

function notebookTextOutput(output) {
  const item = notebookOutputItem(output, 'text/plain');
  return item ? String(item.value) : '';
}

function configurationEvent(changedKey) {
  return {
    affectsConfiguration(key) {
      return key === changedKey;
    },
  };
}

function createVscodeTreeHarness() {
  const warnings = [];
  const errors = [];
  const information = [];
  const createdTreeViews = [];
  const registeredCommands = new Map();
  const progressControllers = [];
  const quickPicks = [];
  let quickPickSelectionId;
  class EventEmitter {
    constructor() {
      this.listeners = new Set();
      this.event = listener => {
        this.listeners.add(listener);
        return { dispose: () => this.listeners.delete(listener) };
      };
    }

    fire(value) {
      [...this.listeners].forEach(listener => listener(value));
    }

    dispose() {
      this.listeners.clear();
    }
  }
  class TreeItem {
    constructor(label, collapsibleState) {
      this.label = label;
      this.collapsibleState = collapsibleState;
    }
  }
  class ThemeIcon {
    constructor(id, color) {
      this.id = id;
      this.color = color;
    }
  }
  class ThemeColor {
    constructor(id) {
      this.id = id;
    }
  }
  class MarkdownString {
    constructor(value) {
      this.value = value;
    }

    toString() {
      return this.value;
    }
  }
  const createCancellationController = () => {
    let canceled = false;
    const listeners = new Set();
    return {
      token: {
        get isCancellationRequested() {
          return canceled;
        },
        onCancellationRequested(listener) {
          listeners.add(listener);
          return { dispose: () => listeners.delete(listener) };
        },
      },
      cancel() {
        if (canceled) {
          return;
        }
        canceled = true;
        [...listeners].forEach(listener => listener());
      },
    };
  };
  const harness = {
    warnings,
    errors,
    information,
    createdTreeViews,
    registeredCommands,
    progressControllers,
    quickPicks,
    setQuickPickSelectionId(value) {
      quickPickSelectionId = value;
    },
    cancelLatestProgress() {
      assert.ok(progressControllers.length > 0, 'no cancellable progress operation was created');
      progressControllers.at(-1).cancel();
    },
    vscode: {
      EventEmitter,
      TreeItem,
      ThemeIcon,
      ThemeColor,
      MarkdownString,
      TreeItemCollapsibleState: { None: 0, Collapsed: 1, Expanded: 2 },
      ProgressLocation: { Notification: 15 },
      commands: {
        registerCommand(id, handler) {
          registeredCommands.set(id, handler);
          return { dispose: () => registeredCommands.delete(id) };
        },
      },
      window: {
        createTreeView(id, options) {
          const view = { id, options, disposed: false };
          createdTreeViews.push(view);
          return { dispose: () => { view.disposed = true; } };
        },
        async withProgress(_options, task) {
          const controller = createCancellationController();
          progressControllers.push(controller);
          return task({}, controller.token);
        },
        showWarningMessage(message) {
          warnings.push(message);
          return undefined;
        },
        showErrorMessage(message) {
          errors.push(message);
          return undefined;
        },
        showInformationMessage(message) {
          information.push(message);
          return undefined;
        },
        showQuickPick(items, options) {
          quickPicks.push({ items, options });
          return items.find(item => item.connection?.id === quickPickSelectionId);
        },
      },
    },
  };
  return harness;
}

function createVscodeRuntimeMock(settings = {}) {
  class EventEmitter {
    constructor() {
      this.listeners = new Set();
      this.event = listener => {
        this.listeners.add(listener);
        return { dispose: () => this.listeners.delete(listener) };
      };
    }

    fire(value) {
      this.listeners.forEach(listener => listener(value));
    }

    dispose() {
      this.listeners.clear();
    }
  }
  return {
    EventEmitter,
    workspace: {
      getConfiguration() {
        return {
          get(key, fallback) {
            return Object.prototype.hasOwnProperty.call(settings, key) ? settings[key] : fallback;
          },
        };
      },
    },
  };
}

function createVscodePanelHarness() {
  const disposeListeners = new Set();
  const messageListeners = new Set();
  const posted = [];
  const webview = {
    cspSource: 'vscode-webview://connection-form-test',
    html: '',
    async postMessage(message) {
      posted.push(message);
      return true;
    },
    onDidReceiveMessage(listener) {
      messageListeners.add(listener);
      return { dispose: () => messageListeners.delete(listener) };
    },
  };
  const panel = {
    webview,
    disposed: false,
    onDidDispose(listener) {
      disposeListeners.add(listener);
      return { dispose: () => disposeListeners.delete(listener) };
    },
    dispose() {
      if (panel.disposed) {
        return;
      }
      panel.disposed = true;
      [...disposeListeners].forEach(listener => listener());
    },
  };
  const harness = {
    posted,
    panel,
    created: undefined,
    vscode: {
      ViewColumn: { Active: 'active' },
      window: {
        createWebviewPanel(viewType, title, column, options) {
          harness.created = { viewType, title, column, options };
          return panel;
        },
      },
    },
  };
  return harness;
}

function createQTextResultsPanelHarness() {
  const panels = [];
  const updates = [];
  const clipboard = [];
  const warnings = [];
  const settings = Object.create(null);
  let warningResponse;
  const context = {
    extensionPath: ROOT,
    globalState: {
      get() {
        return undefined;
      },
      async update() {
        return undefined;
      },
    },
  };

  class Disposable {
    constructor(dispose) {
      this.disposeCallback = dispose;
    }
    dispose() {
      this.disposeCallback();
    }
  }

  const harness = {
    panels,
    updates,
    clipboard,
    warnings,
    context,
    setSetting(key, value) {
      settings[key] = value;
    },
    setWarningResponse(value) {
      warningResponse = value;
    },
    async emitMessage(panelIndex, message) {
      const panel = panels[panelIndex];
      assert.ok(panel, `result panel ${panelIndex} does not exist`);
      [...panel.messageListeners].forEach(listener => listener(message));
      await new Promise(resolve => setImmediate(resolve));
    },
    vscode: {
      ConfigurationTarget: { Global: 'global' },
      Disposable,
      Uri: {
        file(fsPath) {
          return {
            fsPath,
            toString() {
              return `file://${fsPath}`;
            },
          };
        },
      },
      ViewColumn: {
        Active: 'active',
        Beside: 'beside',
        One: 'one',
        Two: 'two',
        Three: 'three',
      },
      ProgressLocation: {
        Window: 'window',
      },
      env: {
        clipboard: {
          async writeText(value) {
            clipboard.push(value);
          },
        },
      },
      workspace: {
        getConfiguration(section) {
          return {
            get(key, fallback) {
              const fullKey = `${section}.${key}`;
              return Object.prototype.hasOwnProperty.call(settings, fullKey) ? settings[fullKey] : fallback;
            },
            async update(key, value, target) {
              const fullKey = `${section}.${key}`;
              settings[fullKey] = value;
              updates.push({ key: fullKey, value, target });
            },
          };
        },
      },
      window: {
        activeTextEditor: undefined,
        createWebviewPanel(viewType, title, viewColumn, options) {
          const disposeListeners = new Set();
          const messageListeners = new Set();
          const viewStateListeners = new Set();
          const postListeners = new Set();
          const posted = [];
          const webview = {
            cspSource: 'vscode-webview://qtext-results-test',
            html: '',
            asWebviewUri(uri) {
              return `vscode-webview-resource://${uri.fsPath}`;
            },
            async postMessage(message) {
              posted.push(message);
              [...postListeners].forEach(listener => listener(message));
              return true;
            },
            onDidReceiveMessage(listener) {
              messageListeners.add(listener);
              return { dispose: () => messageListeners.delete(listener) };
            },
          };
          const panel = {
            viewType,
            title,
            viewColumn,
            options,
            webview,
            posted,
            messageListeners,
            postListeners,
            active: true,
            visible: true,
            disposed: false,
            reveal(column) {
              panel.viewColumn = column;
              panel.visible = true;
              panel.active = true;
            },
            onDidDispose(listener) {
              disposeListeners.add(listener);
              return { dispose: () => disposeListeners.delete(listener) };
            },
            onDidChangeViewState(listener) {
              viewStateListeners.add(listener);
              return { dispose: () => viewStateListeners.delete(listener) };
            },
            dispose() {
              if (panel.disposed) {
                return;
              }
              panel.disposed = true;
              panel.active = false;
              panel.visible = false;
              [...disposeListeners].forEach(listener => listener());
            },
          };
          panels.push(panel);
          return panel;
        },
        showErrorMessage() {
          return undefined;
        },
        showWarningMessage(message, ...items) {
          warnings.push({ message, items });
          return Promise.resolve(warningResponse);
        },
        async withProgress(_options, task) {
          return task();
        },
      },
    },
  };
  return harness;
}

function createScopedConnectionStoreHarness(options) {
  const configurationListeners = new Set();
  const state = {
    global: cloneJson(options.global || []),
    workspace: cloneJson(options.workspace || []),
    folders: new Map(
      (options.folders || []).map(folder => [
        folder.uri,
        cloneJson(folder.connections || []),
      ])
    ),
    committedGlobal: cloneJson(options.global || []),
    committedWorkspace: cloneJson(options.workspace || []),
    committedFolders: new Map(
      (options.folders || []).map(folder => [
        folder.uri,
        cloneJson(folder.connections || []),
      ])
    ),
    activeId: options.activeId,
    secrets: new Map(Object.entries(options.secrets || {})),
    failNextTarget: undefined,
    delayConfigurationPropagation: false,
    pendingConfigurationUpdates: [],
  };
  const folders = [...state.folders.keys()].map(uri => ({
    name: uri.slice(uri.lastIndexOf('/') + 1),
    uri: testUri(uri),
  }));
  const fireConfigurationChange = () => {
    configurationListeners.forEach(listener => listener({
      affectsConfiguration(key) {
        return key === 'vscode-kdb.connections';
      },
    }));
  };
  const configuration = resource => ({
    get(key) {
      assert.strictEqual(key, 'connections');
      if (resource) {
        return cloneJson(state.folders.get(resource.toString()) || state.workspace || state.global);
      }
      return cloneJson(state.workspace.length ? state.workspace : state.global);
    },
    inspect(key) {
      assert.strictEqual(key, 'connections');
      return {
        globalValue: cloneJson(state.global),
        workspaceValue: cloneJson(state.workspace),
        ...(resource
          ? { workspaceFolderValue: cloneJson(state.folders.get(resource.toString()) || []) }
          : {}),
      };
    },
    async update(key, value, target) {
      assert.strictEqual(key, 'connections');
      if (state.failNextTarget === target) {
        state.failNextTarget = undefined;
        throw new Error(`injected ${target} configuration update failure`);
      }
      if (target === 'global') {
        state.committedGlobal = cloneJson(value);
      } else if (target === 'workspace') {
        state.committedWorkspace = cloneJson(value);
      } else if (target === 'workspaceFolder') {
        assert.ok(resource, 'workspace-folder writes require a resource');
        state.committedFolders.set(resource.toString(), cloneJson(value));
      } else {
        assert.fail(`unexpected configuration target ${target}`);
      }
      if (state.delayConfigurationPropagation) {
        state.pendingConfigurationUpdates.push({
          target,
          resource: resource?.toString(),
          value: cloneJson(value),
        });
        return;
      }
      applyConfigurationUpdate(target, resource?.toString(), value);
      fireConfigurationChange();
    },
  });
  const applyConfigurationUpdate = (target, resource, value) => {
    if (target === 'global') {
      state.global = cloneJson(value);
    } else if (target === 'workspace') {
      state.workspace = cloneJson(value);
    } else if (target === 'workspaceFolder') {
      state.folders.set(resource, cloneJson(value));
    }
  };
  const context = {
    subscriptions: [],
    globalState: {
      get() {
        return state.activeId;
      },
      async update(_key, value) {
        state.activeId = value;
      },
    },
    secrets: {
      async get(key) {
        return state.secrets.get(key);
      },
      async store(key, value) {
        state.secrets.set(key, value);
      },
      async delete(key) {
        state.secrets.delete(key);
      },
    },
  };
  const harness = {
    context,
    vscode: {
      ConfigurationTarget: {
        Global: 'global',
        Workspace: 'workspace',
        WorkspaceFolder: 'workspaceFolder',
      },
      Uri: {
        parse(value) {
          return testUri(value);
        },
      },
      workspace: {
        workspaceFolders: folders,
        workspaceFile: testUri('file:///workspace/project.code-workspace'),
        getConfiguration(_section, resource) {
          return configuration(resource);
        },
        onDidChangeConfiguration(listener) {
          configurationListeners.add(listener);
          return { dispose: () => configurationListeners.delete(listener) };
        },
      },
    },
    get globalConnections() {
      return cloneJson(state.global);
    },
    get workspaceConnections() {
      return cloneJson(state.workspace);
    },
    get activeId() {
      return state.activeId;
    },
    get pendingConfigurationUpdates() {
      return state.pendingConfigurationUpdates.length;
    },
    folderConnections(uri) {
      return cloneJson(state.folders.get(uri) || []);
    },
    secretFor(id) {
      return state.secrets.get(`vscode-kdb.connectionPassword.${id}`);
    },
    applyExternalGlobal(connections) {
      state.global = cloneJson(connections);
      state.committedGlobal = cloneJson(connections);
      fireConfigurationChange();
    },
    failNextScopeUpdate(target) {
      state.failNextTarget = target;
    },
    set delayConfigurationPropagation(value) {
      state.delayConfigurationPropagation = value;
    },
    flushConfigurationUpdate(index = 0) {
      const [pending] = state.pendingConfigurationUpdates.splice(index, 1);
      assert.ok(pending, `no pending scoped configuration update at index ${index}`);
      applyConfigurationUpdate(pending.target, pending.resource, pending.value);
      fireConfigurationChange();
    },
  };
  return harness;
}

function createVscodeStoreHarness() {
  const configurationListeners = new Set();
  const state = {
    activeId: undefined,
    committedActiveId: undefined,
    connections: [],
    committedConnections: [],
    secrets: new Map(),
    failSecretStore: 0,
    failSecretDelete: 0,
    failSecretGet: 0,
    failConfigurationUpdate: 0,
    failActiveUpdate: 0,
    delayConfigurationPropagation: false,
    delayActivePropagation: false,
    pendingConfigurationUpdates: [],
    pendingActiveUpdates: [],
    nextSecretGetBarrier: undefined,
    nextConfigurationUpdateBarrier: undefined,
    nextConfigurationResolutionBarrier: undefined,
    secretGetCalls: 0,
    secretStoreCalls: 0,
    secretDeleteCalls: 0,
  };
  const configuration = {
    get(key) {
      assert.strictEqual(key, 'connections');
      return cloneJson(state.connections);
    },
    inspect(key) {
      assert.strictEqual(key, 'connections');
      return { globalValue: cloneJson(state.connections) };
    },
    async update(key, value, target) {
      assert.strictEqual(key, 'connections');
      assert.strictEqual(target, 'global');
      const barrier = state.nextConfigurationUpdateBarrier;
      if (barrier) {
        state.nextConfigurationUpdateBarrier = undefined;
        barrier.started.resolve();
        await barrier.release.promise;
      }
      if (state.failConfigurationUpdate > 0) {
        state.failConfigurationUpdate--;
        throw new Error('injected configuration update failure');
      }
      state.committedConnections = cloneJson(value);
      if (state.delayConfigurationPropagation) {
        state.pendingConfigurationUpdates.push(cloneJson(value));
      } else {
        state.connections = cloneJson(value);
        fireConfigurationChange();
      }
      const resolutionBarrier = state.nextConfigurationResolutionBarrier;
      if (resolutionBarrier) {
        state.nextConfigurationResolutionBarrier = undefined;
        resolutionBarrier.started.resolve();
        await resolutionBarrier.release.promise;
      }
    },
  };
  function fireConfigurationChange() {
    for (const listener of configurationListeners) {
      listener({
        affectsConfiguration(key) {
          return key === 'vscode-kdb.connections';
        },
      });
    }
  }
  const context = {
    subscriptions: [],
    globalState: {
      get() {
        return state.activeId;
      },
      async update(_key, value) {
        if (state.failActiveUpdate > 0) {
          state.failActiveUpdate--;
          throw new Error('injected active-state update failure');
        }
        state.committedActiveId = value;
        if (state.delayActivePropagation) {
          state.pendingActiveUpdates.push(value);
          return;
        }
        state.activeId = value;
      },
    },
    secrets: {
      async get(key) {
        state.secretGetCalls++;
        const barrier = state.nextSecretGetBarrier;
        if (barrier) {
          state.nextSecretGetBarrier = undefined;
          barrier.started.resolve();
          await barrier.release.promise;
        }
        if (state.failSecretGet > 0) {
          state.failSecretGet--;
          throw new Error('injected SecretStorage get failure');
        }
        return state.secrets.get(key);
      },
      async store(key, value) {
        state.secretStoreCalls++;
        if (state.failSecretStore > 0) {
          state.failSecretStore--;
          throw new Error('injected SecretStorage store failure');
        }
        state.secrets.set(key, value);
      },
      async delete(key) {
        state.secretDeleteCalls++;
        if (state.failSecretDelete > 0) {
          state.failSecretDelete--;
          throw new Error('injected SecretStorage delete failure');
        }
        state.secrets.delete(key);
      },
    },
  };
  const harness = {
    vscode: {
      ConfigurationTarget: { Global: 'global' },
      workspace: {
        getConfiguration: () => configuration,
        onDidChangeConfiguration(listener) {
          configurationListeners.add(listener);
          return { dispose: () => configurationListeners.delete(listener) };
        },
      },
    },
    context,
    get connections() {
      return cloneJson(state.connections);
    },
    get committedConnections() {
      return cloneJson(state.committedConnections);
    },
    get activeId() {
      return state.activeId;
    },
    get committedActiveId() {
      return state.committedActiveId;
    },
    set failSecretStore(value) {
      state.failSecretStore = value;
    },
    set failSecretDelete(value) {
      state.failSecretDelete = value;
    },
    set failSecretGet(value) {
      state.failSecretGet = value;
    },
    set failConfigurationUpdate(value) {
      state.failConfigurationUpdate = value;
    },
    set failActiveUpdate(value) {
      state.failActiveUpdate = value;
    },
    set delayConfigurationPropagation(value) {
      state.delayConfigurationPropagation = value;
    },
    set delayActivePropagation(value) {
      state.delayActivePropagation = value;
    },
    delayNextSecretGet() {
      assert.strictEqual(state.nextSecretGetBarrier, undefined);
      const started = deferred();
      const release = deferred();
      state.nextSecretGetBarrier = { started, release };
      return {
        started: started.promise,
        release: () => release.resolve(),
      };
    },
    delayNextConfigurationUpdate() {
      assert.strictEqual(state.nextConfigurationUpdateBarrier, undefined);
      const started = deferred();
      const release = deferred();
      state.nextConfigurationUpdateBarrier = { started, release };
      return {
        started: started.promise,
        release: () => release.resolve(),
      };
    },
    delayNextConfigurationResolution() {
      assert.strictEqual(state.nextConfigurationResolutionBarrier, undefined);
      const started = deferred();
      const release = deferred();
      state.nextConfigurationResolutionBarrier = { started, release };
      return {
        started: started.promise,
        release: () => release.resolve(),
      };
    },
    get pendingConfigurationUpdates() {
      return state.pendingConfigurationUpdates.length;
    },
    get pendingActiveUpdates() {
      return state.pendingActiveUpdates.slice();
    },
    flushNextConfigurationPropagation() {
      const connections = state.pendingConfigurationUpdates.shift();
      if (connections === undefined) {
        return false;
      }
      state.connections = cloneJson(connections);
      fireConfigurationChange();
      return true;
    },
    flushPropagation() {
      while (harness.flushNextConfigurationPropagation()) {
        // Apply and notify one acknowledged setting snapshot at a time.
      }
      for (const activeId of state.pendingActiveUpdates.splice(0)) {
        state.activeId = activeId;
      }
    },
    reloadConfiguration() {
      state.pendingConfigurationUpdates.length = 0;
      state.pendingActiveUpdates.length = 0;
      state.connections = cloneJson(state.committedConnections);
      state.activeId = state.committedActiveId;
    },
    emitConfigurationChange() {
      fireConfigurationChange();
    },
    applyExternalConnections(connections) {
      state.pendingConfigurationUpdates.length = 0;
      state.connections = cloneJson(connections);
      state.committedConnections = cloneJson(connections);
      fireConfigurationChange();
    },
    get secretCalls() {
      return {
        get: state.secretGetCalls,
        store: state.secretStoreCalls,
        delete: state.secretDeleteCalls,
      };
    },
    secretFor(id) {
      return state.secrets.get(`vscode-kdb.connectionPassword.${id}`);
    },
  };
  return harness;
}

function legacySqlToolsProfile(overrides = {}) {
  return {
    driver: 'KDB',
    name: 'Legacy q',
    server: 'localhost',
    port: 5000,
    ...overrides,
  };
}

function createSqlToolsConfigurationApi(options = {}) {
  const folders = options.folders || [];
  const rootConfiguration = {
    inspect(key) {
      assert.strictEqual(key, 'connections');
      return options.rootInspection;
    },
    get(key) {
      assert.strictEqual(key, 'connections');
      return options.rootEffective;
    },
  };
  const folderConfigurations = new Map(folders.map(folder => [
    folder.uri,
    {
      inspect(key) {
        assert.strictEqual(key, 'connections');
        return folder.inspection;
      },
      get(key) {
        assert.strictEqual(key, 'connections');
        return folder.effective;
      },
    },
  ]));
  return {
    workspace: {
      workspaceFolders: folders.map(folder => ({
        name: folder.name,
        uri: folder.uri,
      })),
      getConfiguration(section, resource) {
        assert.strictEqual(section, 'sqltools');
        if (resource === undefined) {
          return rootConfiguration;
        }
        const configuration = folderConfigurations.get(resource);
        assert.ok(configuration, 'unexpected workspace-folder configuration resource');
        return configuration;
      },
    },
  };
}

function createMigrationCommandHarness(options = {}) {
  const configurationListeners = new Set();
  const state = {
    activeId: options.initialActiveId,
    connections: cloneJson(options.initialConnections || []),
    secrets: new Map(),
    sqlToolsGlobal: options.sqlToolsGlobal || [],
    sqlToolsUpdates: 0,
    failSecretStore: !!options.failSecretStore,
    nextConnectionId: 1,
    treeRefreshes: 0,
  };
  for (const [id, password] of Object.entries(options.initialSecrets || {})) {
    state.secrets.set(`vscode-kdb.connectionPassword.${id}`, password);
  }

  const quickPicks = [];
  const conflictPicks = [];
  const inputBoxes = [];
  const warnings = [];
  const information = [];
  const executedCommands = [];

  const sqlToolsConfiguration = {
    inspect(key) {
      assert.strictEqual(key, 'connections');
      return {
        key: 'sqltools.connections',
        globalValue: state.sqlToolsGlobal,
      };
    },
    get(key) {
      assert.strictEqual(key, 'connections');
      return state.sqlToolsGlobal;
    },
    async update() {
      state.sqlToolsUpdates++;
      throw new Error('the SQLTools source setting must remain read-only');
    },
  };
  const kxConfiguration = {
    get(key) {
      assert.strictEqual(key, 'connections');
      return cloneJson(state.connections);
    },
    inspect(key) {
      assert.strictEqual(key, 'connections');
      return { globalValue: cloneJson(state.connections) };
    },
    async update(key, value, target) {
      assert.strictEqual(key, 'connections');
      assert.strictEqual(target, 'global');
      state.connections = cloneJson(value);
      for (const listener of configurationListeners) {
        listener({
          affectsConfiguration(candidate) {
            return candidate === 'vscode-kdb.connections';
          },
        });
      }
    },
  };

  const vscode = {
    ConfigurationTarget: { Global: 'global' },
    workspace: {
      workspaceFolders: undefined,
      onDidChangeConfiguration(listener) {
        configurationListeners.add(listener);
        return { dispose: () => configurationListeners.delete(listener) };
      },
      getConfiguration(section) {
        if (section === 'sqltools') {
          return sqlToolsConfiguration;
        }
        assert.strictEqual(section, 'vscode-kdb');
        return kxConfiguration;
      },
    },
    window: {
      createQuickPick() {
        const selectionListeners = new Set();
        const acceptListeners = new Set();
        const hideListeners = new Set();
        let selectedItems = [];
        let hidden = false;
        const quickPick = {
          title: '',
          placeholder: '',
          canSelectMany: false,
          ignoreFocusOut: false,
          matchOnDescription: false,
          matchOnDetail: false,
          items: [],
          get selectedItems() {
            return selectedItems;
          },
          set selectedItems(items) {
            selectedItems = items;
            [...selectionListeners].forEach(listener => listener(items));
          },
          onDidChangeSelection(listener) {
            selectionListeners.add(listener);
            return { dispose: () => selectionListeners.delete(listener) };
          },
          onDidAccept(listener) {
            acceptListeners.add(listener);
            return { dispose: () => acceptListeners.delete(listener) };
          },
          onDidHide(listener) {
            hideListeners.add(listener);
            return { dispose: () => hideListeners.delete(listener) };
          },
          show() {
            quickPick.selectedItems = options.selectUnsupported
              ? [...quickPick.items]
              : quickPick.items.filter(item =>
                item.selectable &&
                (!options.selectCandidate || options.selectCandidate(item.candidate))
              );
            [...acceptListeners].forEach(listener => listener());
          },
          hide() {
            if (hidden) {
              return;
            }
            hidden = true;
            [...hideListeners].forEach(listener => listener());
          },
          dispose() {
            selectionListeners.clear();
            acceptListeners.clear();
            hideListeners.clear();
          },
        };
        quickPicks.push(quickPick);
        return quickPick;
      },
      async showQuickPick(items, pickerOptions) {
        conflictPicks.push({ items, options: pickerOptions });
        return items.find(item => item.action === options.conflictDecision);
      },
      async showInputBox(inputOptions) {
        inputBoxes.push(inputOptions);
        return options.renameValue;
      },
      async showWarningMessage(message, modal, ...actions) {
        warnings.push({ message, modal, actions });
        if (actions.includes('Copy Passwords and Import')) {
          if (options.sqlToolsAfterPasswordDecision) {
            state.sqlToolsGlobal = options.sqlToolsAfterPasswordDecision;
          }
          if (options.kxConnectionsAfterPasswordDecision) {
            state.connections = cloneJson(options.kxConnectionsAfterPasswordDecision);
          }
          return options.passwordDecision;
        }
        return undefined;
      },
      async showInformationMessage(message, ...actions) {
        information.push({ message, actions });
        return options.reviewAfterImport && actions.includes('Review Imported Connection')
          ? 'Review Imported Connection'
          : undefined;
      },
    },
    commands: {
      async executeCommand(command, ...args) {
        executedCommands.push({ command, args });
      },
    },
  };
  const context = {
    subscriptions: [],
    globalState: {
      get() {
        return state.activeId;
      },
      async update(_key, value) {
        state.activeId = value;
      },
    },
    secrets: {
      async get(key) {
        return state.secrets.get(key);
      },
      async store(key, value) {
        if (state.failSecretStore) {
          throw new Error('injected SecretStorage store failure');
        }
        state.secrets.set(key, value);
      },
      async delete(key) {
        state.secrets.delete(key);
      },
    },
  };
  const { ConnectionStore } = requireOutWithVscode('connection-store', vscode);
  const store = new ConnectionStore(context);
  store.newConnectionId = () => `kx-import-${state.nextConnectionId++}`;
  const tree = {
    refresh() {
      state.treeRefreshes++;
    },
  };
  const command = new ConnectionMigrationCommand(vscode, store, tree);

  return {
    command,
    quickPicks,
    conflictPicks,
    inputBoxes,
    warnings,
    information,
    executedCommands,
    get connections() {
      return cloneJson(state.connections);
    },
    get activeId() {
      return state.activeId;
    },
    get treeRefreshes() {
      return state.treeRefreshes;
    },
    secretFor(id) {
      return state.secrets.get(`vscode-kdb.connectionPassword.${id}`);
    },
    sourcePassword() {
      const source = state.sqlToolsGlobal.find(profile =>
        profile && typeof profile === 'object' && typeof profile.password === 'string');
      return source && source.password;
    },
    get sqlToolsUpdates() {
      return state.sqlToolsUpdates;
    },
  };
}

function cloneJson(value) {
  return JSON.parse(JSON.stringify(value));
}

function cloneNotebookHostValue(value) {
  if (value instanceof Uint8Array) {
    return Uint8Array.from(value);
  }
  if (Array.isArray(value)) {
    return value.map(cloneNotebookHostValue);
  }
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).reverse().map(([key, nested]) => [
      key,
      cloneNotebookHostValue(nested),
    ]));
  }
  return value;
}

function hex(value) {
  return Buffer.from(value.replace(/\s/g, ''), 'hex');
}

function semanticQ(value) {
  return isQRuntimeValue(value) ? qValueToSemanticPrimitive(value) : value;
}

function qTable(columns, vectors) {
  return Buffer.concat([
    int8(98),
    Buffer.from([0]),
    int8(99),
    symbolVector(columns),
    genericList(vectors),
  ]);
}

function qResponse(payload) {
  const message = Buffer.alloc(8 + payload.length);
  message.writeUInt8(1, 0);
  message.writeUInt8(2, 1);
  message.writeInt32LE(message.length, 4);
  payload.copy(message, 8);
  return message;
}

function genericList(items) {
  return Buffer.concat([vectorHeader(0, items.length), ...items]);
}

function symbolVector(values) {
  return Buffer.concat([vectorHeader(11, values.length), ...values.map(value => cString(value))]);
}

function intVector(values) {
  return typedIntVector(6, values);
}

function typedIntVector(type, values) {
  const body = Buffer.alloc(values.length * 4);
  values.forEach((value, index) => body.writeInt32LE(value, index * 4));
  return Buffer.concat([vectorHeader(type, values.length), body]);
}

function longVector(type, values) {
  const body = Buffer.alloc(values.length * 8);
  values.forEach((value, index) => body.writeBigInt64LE(BigInt(value), index * 8));
  return Buffer.concat([vectorHeader(type, values.length), body]);
}

function doubleVector(type, values) {
  const body = Buffer.alloc(values.length * 8);
  values.forEach((value, index) => body.writeDoubleLE(value, index * 8));
  return Buffer.concat([vectorHeader(type, values.length), body]);
}

function vectorHeader(type, length) {
  const header = Buffer.alloc(6);
  header.writeInt8(type, 0);
  header.writeUInt8(0, 1);
  header.writeInt32LE(length, 2);
  return header;
}

function int8(value) {
  const result = Buffer.alloc(1);
  result.writeInt8(value, 0);
  return result;
}

function cString(value) {
  return Buffer.from(`${value}\0`, 'utf8');
}

function listen(server) {
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });
}

function closeServer(server) {
  return new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
}

async function assertCompletesWithin(label, operation, timeoutMs) {
  let timeout;
  try {
    return await Promise.race([
      operation(),
      new Promise((_, reject) => {
        timeout = setTimeout(() => reject(new Error(`${label} did not complete within ${timeoutMs} ms`)), timeoutMs);
      }),
    ]);
  } finally {
    if (timeout) {
      clearTimeout(timeout);
    }
  }
}

async function unusedLoopbackPort() {
  const server = net.createServer();
  await listen(server);
  const address = server.address();
  const port = address && typeof address === 'object' ? address.port : 0;
  await closeServer(server);
  return port;
}

function connectToLoopback(port) {
  return new Promise((resolve, reject) => {
    const socket = net.createConnection({ host: '127.0.0.1', port });
    socket.once('connect', () => {
      socket.destroy();
      resolve();
    });
    socket.once('error', reject);
  });
}

function assertKeybinding(keybindings, command, key, mac) {
  const binding = keybindings.find(candidate => candidate.command === command);
  assert.ok(binding, `missing keybinding for ${command}`);
  assert.strictEqual(String(binding.key).toLowerCase(), key);
  assert.strictEqual(String(binding.mac).toLowerCase(), mac);
  assert.match(String(binding.when || ''), /editorTextFocus/);
  assert.match(String(binding.when || ''), /q/);
}

function isConnectionTestFailure(error, phase) {
  return error instanceof Error &&
    error.name === 'ConnectionTestError' &&
    error.phase === phase;
}

function assertNoSqlToolsRuntimeReference(source, label) {
  const forbidden = [
    /@sqltools\//i,
    /sqltools\.connections/i,
    /["']sqltools\./i,
    /\.session\.sql/i,
    /kdb-sqltools/i,
  ];
  forbidden.forEach(pattern => assert.ok(!pattern.test(source), `${label} contains forbidden standalone dependency/path ${pattern}`));
}

function assertSqlToolsMigrationBridgeSource(source, label) {
  for (const alias of [
    'KDB',
    'kdb+',
    'kdb',
    'kdb-sqltools',
    'DanielAlonso.kdb-sqltools',
  ]) {
    assert.ok(source.includes(`'${alias}'`), `${label} is missing the exact legacy alias ${alias}`);
  }
  assert.match(source, /const SQLTOOLS_CONFIGURATION_SECTION = 'sqltools'/);
  assert.match(source, /const SQLTOOLS_CONNECTIONS_SETTING = 'connections'/);
  assert.match(
    source,
    /getConfiguration\(SQLTOOLS_CONFIGURATION_SECTION(?:,\s*folder\.uri)?\)/
  );
  assert.ok(!/sshOptions/.test(source), `${label} must not inspect or copy SQLTools SSH options`);
  const forbidden = [
    /@sqltools\//i,
    /\.session\.sql/i,
    /extensions\.getExtension/i,
    /(?:registerCommand|executeCommand)\(\s*['"]sqltools\./i,
    /onDidChangeConfiguration/i,
    /setInterval\s*\(/i,
    /\b(?:console|logger)\s*\./i,
  ];
  forbidden.forEach(pattern => assert.ok(
    !pattern.test(source),
    `${label} exceeds the read-only migration bridge boundary ${pattern}`
  ));
}

function assertNoVscodeQRuntimeReference(source, label) {
  const forbidden = [
    /jshinonome\/vscode-q/i,
    /(?:from|require\s*\()\s*['"][^'"]*vscode-q/i,
    /[\\/]vscode-q[\\/]/i,
  ];
  forbidden.forEach(pattern => assert.ok(
    !pattern.test(source),
    `${label} contains forbidden q Professional/vscode-q runtime source or asset reference ${pattern}`
  ));
}

function walkFiles(directory) {
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap(entry => {
    const target = path.join(directory, entry.name);
    return entry.isDirectory() ? walkFiles(target) : [target];
  });
}

function sourcesFromDirectory(directory) {
  return walkFiles(directory)
    .filter(file => file.endsWith('.ts'))
    .map(file => [file, fs.readFileSync(file, 'utf8')]);
}

function readSource(fileName) {
  return fs.readFileSync(path.join(ROOT, 'src', fileName), 'utf8');
}

function sourceSection(source, startNeedle, endNeedle) {
  const start = source.indexOf(startNeedle);
  const end = source.indexOf(endNeedle, start);
  assert.ok(start >= 0 && end > start, `cannot find source section ${startNeedle} .. ${endNeedle}`);
  return source.slice(start, end);
}
